// fayl: lib/fs.ts
type Dir = { [name: string]: Dir | string }
export const tree: Dir = { hujjatlar: { "2025": { "shartnoma.pdf": "12 KB" } }, rasmlar: { "osh.jpg": "340 KB" } }

export function resolve(path: string[]) {
  let node: Dir | string = tree
  for (const p of path) {
    if (typeof node === "string" || !(p in node)) return null
    node = node[p]
  }
  return node
}

