      <h1>/{path.join("/")}</h1>
      {typeof node === "string" ? <p>Fayl hajmi: {node}</p> : <ul>{Object.keys(node).map((n) => <li key={n}>📁 {n}</li>)}</ul>}
    </main>
  )
}

