// fayl: app/events/[date]/page.tsx
import { notFound } from "next/navigation"

export default async function Events({ params }: { params: Promise<{ date: string }> }) {
  const { date } = await params
  const d = new Date(date + "T00:00:00Z")
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== date) notFound()
  const weekday = ["Yakshanba", "Dushanba", "Seshanba", "Chorshanba", "Payshanba", "Juma", "Shanba"][d.getUTCDay()]
  return <h1>{date} ({weekday}) tadbirlari</h1>
}

