// fayl: app/products/page.tsx
import Link from "next/link"

const all = Array.from({ length: 7 }, (_, i) => `Mahsulot ${i + 1}`)

export default async function Products({ searchParams }: { searchParams: Promise<{ page?: string }> }) {
  const page = Number((await searchParams).page ?? 1)
  const items = all.slice((page - 1) * 3, page * 3)
  const pages = Math.ceil(all.length / 3)
  return (
    <main>
      <ul>{items.map((i) => <li key={i}>{i}</li>)}</ul>
      {page > 1 && <Link href={`?page=${page - 1}`}>← Oldingi</Link>} {page}/{pages}{" "}
      {page < pages && <Link href={`?page=${page + 1}`}>Keyingi →</Link>}
    </main>
  )
}

