import Link from "next/link"

export default async function Shop({ searchParams }: { searchParams: Promise<Record<string, string>> }) {
  const sp = await searchParams
  const withParam = (k: string, v: string) => "?" + new URLSearchParams({ ...sp, [k]: v }).toString()
  return (
    <main>
      <p>Joriy: {new URLSearchParams(sp).toString() || "(bo'sh)"}</p>
      <Link href={withParam("sort", "price")}>Narx bo'yicha</Link> | <Link href={withParam("page", "2")}>2-sahifa</Link>
    </main>
  )
}

// fayl: app/account/page.tsx
import { cookies } from "next/headers"
import { redirect } from "next/navigation"

export default async function Account() {
  if (!(await cookies()).get("session")) redirect("/login?next=/account")
  return <h1>Hisobim</h1>
}

// fayl: app/login/page.tsx
import { cookies } from "next/headers"
import { redirect } from "next/navigation"

async function login(formData: FormData) {
  "use server"
  ;(await cookies()).set("session", "ok")
  const next = String(formData.get("next") || "/")
  redirect(next.startsWith("/") ? next : "/")
}

export default async function Login({ searchParams }: { searchParams: Promise<{ next?: string }> }) {
  const { next = "/" } = await searchParams
  return (
    <form action={login}>
      <input type="hidden" name="next" value={next} />
      <button>Kirish</button>
    </form>
  )
}

